package de.igslandstuhl.database.attendance;import static org.junit.jupiter.api.Assertions.*;import de.igslandstuhl.database.api.*;import com.google.gson.*;import java.io.*;import java.nio.charset.StandardCharsets;import org.junit.jupiter.api.Test;
class AttendanceSecurityTest{@Test void teachersAreStaffButNeverAcceptedAsStudentIdentity(){Teacher teacher=new Teacher(12,"T","Eacher","teacher@example.test","hash");assertTrue(AttendanceRequests.staff(teacher));assertNull(AttendanceRequests.strictStudent(teacher));assertNull(AttendanceRequests.strictStudent(User.ANONYMOUS));}@Test void manualEndpointRequiresTeacherRole()throws Exception{try(InputStream in=getClass().getResourceAsStream("/meta/paths/post_paths.json")){assertNotNull(in);JsonObject root=JsonParser.parseString(new String(in.readAllBytes(),StandardCharsets.UTF_8)).getAsJsonObject();assertEquals("teacher",root.getAsJsonObject("/attendance-manual-arrival").get("access_level").getAsString());}}}
